package handler

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestListAllItems(t *testing.T) {
	req := httptest.NewRequest("GET", "/items", nil)
	rr := httptest.NewRecorder()
	ListItems(rr, req)
	var result []Item
	if err := json.NewDecoder(rr.Body).Decode(&result); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(result) != 10 {
		t.Errorf("want 10 items, got %d", len(result))
	}
}

func TestPaginationFirstPage(t *testing.T) {
	req := httptest.NewRequest("GET", "/items?page=1&limit=3", nil)
	rr := httptest.NewRecorder()
	ListItems(rr, req)
	var result []Item
	if err := json.NewDecoder(rr.Body).Decode(&result); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(result) != 3 {
		t.Errorf("page=1 limit=3: want 3 items, got %d", len(result))
	}
	if result[0].ID != 1 {
		t.Errorf("first item should have ID=1, got %d", result[0].ID)
	}
}

func TestPaginationSecondPage(t *testing.T) {
	req := httptest.NewRequest("GET", "/items?page=2&limit=3", nil)
	rr := httptest.NewRecorder()
	ListItems(rr, req)
	var result []Item
	if err := json.NewDecoder(rr.Body).Decode(&result); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(result) != 3 {
		t.Errorf("page=2 limit=3: want 3 items, got %d", len(result))
	}
	if result[0].ID != 4 {
		t.Errorf("second page first item should have ID=4, got %d", result[0].ID)
	}
}

func TestPaginationLastPage(t *testing.T) {
	req := httptest.NewRequest("GET", "/items?page=4&limit=3", nil)
	rr := httptest.NewRecorder()
	ListItems(rr, req)
	var result []Item
	if err := json.NewDecoder(rr.Body).Decode(&result); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if len(result) != 1 {
		t.Errorf("last page (page=4 limit=3): want 1 item, got %d", len(result))
	}
}
